"use client";
import {useState} from "react";
type Student={id:string;name:string;admissionNo:string};
export default function FeeForm({students}:{students:Student[]}){
 const [msg,setMsg]=useState("");
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch("/api/fees",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});setMsg(r.ok?"Fee record saved.":"Could not save fee.");if(r.ok)e.currentTarget.reset();}
 return <div className="card"><h2>Add Fee Record</h2><form onSubmit={submit} className="grid grid-2">
 <div><label className="label">Student</label><select className="select" name="studentId" required>{students.map(s=><option key={s.id} value={s.id}>{s.admissionNo} — {s.name}</option>)}</select></div>
 <div><label className="label">Academic Year</label><input className="input" name="academicYear" defaultValue="2026-27" required/></div>
 <div><label className="label">Total Amount</label><input className="input" name="amount" type="number" min="0" required/></div>
 <div><label className="label">Paid Amount</label><input className="input" name="paidAmount" type="number" min="0" defaultValue="0" required/></div>
 <div><label className="label">Due Date</label><input className="input" name="dueDate" type="date" required/></div>
 <div><label className="label">Status</label><select className="select" name="status"><option>PENDING</option><option>PARTIAL</option><option>PAID</option></select></div>
 <div><button className="btn btn-primary">Save Fee</button></div></form>{msg&&<p className="muted">{msg}</p>}</div>
}
